package com.memoflow.data
import androidx.room.*
import kotlinx.coroutines.flow.Flow
@Entity(tableName="audio_chunks") data class AudioChunkEntity(@PrimaryKey val id:String,val deviceId:String,val startTimeUtcMs:Long,val endTimeUtcMs:Long,val durationMs:Long,val audioPath:String,val codec:String,val container:String,val sampleRate:Int,val channels:Int,val bitrate:Int,val fileSize:Long,val checksumSha256:String,val state:String,val schemaVersion:Int)
@Entity(tableName="audio_ranges",primaryKeys=["chunkId","startOffsetMs","endOffsetMs"]) data class AudioRangeEntity(val chunkId:String,val startOffsetMs:Long,val endOffsetMs:Long,val type:String,val confidence:Float?,val modelId:String?,val modelVersion:String?)
@Dao interface ChunkDao { @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(chunk:AudioChunkEntity); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun insertRanges(ranges:List<AudioRangeEntity>); @Query("SELECT * FROM audio_chunks ORDER BY startTimeUtcMs DESC") fun observe():Flow<List<AudioChunkEntity>>; @Query("SELECT * FROM audio_chunks WHERE state IN ('COMPLETE','UPLOAD_PENDING','FAILED') ORDER BY startTimeUtcMs") suspend fun pending():List<AudioChunkEntity>; @Query("UPDATE audio_chunks SET state=:state WHERE id=:id") suspend fun updateState(id:String,state:String) }
@Database(entities=[AudioChunkEntity::class,AudioRangeEntity::class],version=1,exportSchema=false) abstract class MemoDatabase:RoomDatabase(){abstract fun chunks():ChunkDao; companion object { @Volatile private var INSTANCE:MemoDatabase?=null; fun get(context:android.content.Context)=INSTANCE?:synchronized(this){INSTANCE?:Room.databaseBuilder(context, MemoDatabase::class.java,"memoflow.db").build().also{INSTANCE=it}} }}
